<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes; use Illuminate\Database\Eloquent\Relations\BelongsToMany; use Illuminate\Database\Eloquent\Relations\HasMany;
class MeetingRoom extends Model { use SoftDeletes; protected $fillable=['name','code','location','capacity','description','image_path','opens_at','closes_at','is_active']; protected function casts(): array { return ['is_active'=>'boolean']; } public function facilities(): BelongsToMany{return $this->belongsToMany(Facility::class);} public function bookings(): HasMany{return $this->hasMany(Booking::class);} }
